--- /dev/null
+++ b/tests/unit/cluster/cluster-shards.tcl
@@ -0,0 +1,111 @@
+proc cluster_shards_allocate_slots {masters replicas} {
+    R 0 cluster addslotsrange 0 1000 1002 5460
+    R 1 cluster addslotsrange 1001 1001 5461 10922
+    R 2 cluster addslotsrange 10923 16383
+}
+
+proc cluster_shards_find_shard {shards node_id} {
+    foreach shard $shards {
+        foreach node [dict get $shard nodes] {
+            if {[dict get $node id] eq $node_id} {
+                return $shard
+            }
+        }
+    }
+    fail "No shard found for node $node_id"
+}
+
+start_cluster 4 3 {tags {external:skip cluster}} {
+    set node_ids {}
+    for {set j 0} {$j < 7} {incr j} {
+        lappend node_ids [R $j cluster myid]
+    }
+    set expected_slots [list {0 1000 1002 5460} {1001 1001 5461 10922} {10923 16383} {}]
+
+    test "CLUSTER SHARDS reports slot ranges on primaries and replicas" {
+        for {set ref 0} {$ref < 7} {incr ref} {
+            set shards [R $ref cluster shards]
+            assert_equal 4 [llength $shards]
+            for {set node 0} {$node < 7} {incr node} {
+                set shard [cluster_shards_find_shard $shards [lindex $node_ids $node]]
+                set primary [expr {$node < 4 ? $node : $node - 4}]
+                assert_equal [lindex $expected_slots $primary] [dict get $shard slots]
+            }
+        }
+    }
+
+    test "CLUSTER SHARDS reports empty slots for a slotless shard" {
+        for {set ref 0} {$ref < 7} {incr ref} {
+            set shard [cluster_shards_find_shard [R $ref cluster shards] [lindex $node_ids 3]]
+            assert_equal {} [dict get $shard slots]
+            assert_equal 1 [llength [dict get $shard nodes]]
+        }
+    }
+
+    set paused_pid [srv 0 pid]
+    test "Promote a replica while its primary is stopped" {
+        wait_for_sync [srv -4 client]
+        pause_process $paused_pid
+        R 4 cluster failover takeover
+        for {set ref 1} {$ref < 7} {incr ref} {
+            wait_for_condition 1000 50 {
+                [lindex [R $ref cluster slots] 0 2 2] eq [lindex $node_ids 4]
+            } else {
+                fail "Node $ref did not learn the promoted primary's slot ownership"
+            }
+            wait_node_marked_fail $ref [lindex $node_ids 0]
+        }
+    }
+
+    test "CLUSTER SHARDS retains slot ranges after failover with a failed primary" {
+        for {set ref 1} {$ref < 7} {incr ref} {
+            for {set query 0} {$query < 2} {incr query} {
+                set shards [R $ref cluster shards]
+                assert_equal 4 [llength $shards]
+                set shard [cluster_shards_find_shard $shards [lindex $node_ids 0]]
+                assert_equal 2 [llength [dict get $shard nodes]]
+                foreach node [dict get $shard nodes] {
+                    assert_equal master [dict get $node role]
+                    if {[dict get $node id] eq [lindex $node_ids 0]} {
+                        assert_equal fail [dict get $node health]
+                    } else {
+                        assert_equal [lindex $node_ids 4] [dict get $node id]
+                        assert_equal online [dict get $node health]
+                    }
+                }
+                for {set primary 0} {$primary < 4} {incr primary} {
+                    set shard [cluster_shards_find_shard $shards [lindex $node_ids $primary]]
+                    assert_equal [lindex $expected_slots $primary] [dict get $shard slots]
+                }
+            }
+        }
+    }
+
+    test "The old primary rejoins as a replica" {
+        resume_process $paused_pid
+        wait_for_condition 1000 50 {
+            [s 0 role] eq {slave}
+        } else {
+            fail "Old primary was not converted into a replica"
+        }
+        wait_for_cluster_propagation
+    }
+
+    test "CLUSTER SHARDS retains slot ranges after the old primary rejoins" {
+        for {set ref 0} {$ref < 7} {incr ref} {
+            set shards [R $ref cluster shards]
+            for {set primary 0} {$primary < 4} {incr primary} {
+                set shard [cluster_shards_find_shard $shards [lindex $node_ids $primary]]
+                assert_equal [lindex $expected_slots $primary] [dict get $shard slots]
+            }
+        }
+    }
+} cluster_shards_allocate_slots
PATCH
